import React, { Component } from "react";
import "./Signup.css";
import FormJson from "./formid";
import PagesJson from "./PagesJson";

export default class Signup extends Component {
    render() {
        const idform = FormJson.find(item => item.formId === 3);
        const contantformm=idform.content;
        return (
            <div className="content-container">
                <div className="formbox">
                    <div className="button-box">
                        <div id="btn"></div>
                        <button type="button" className="toggle-btn">Log In</button>
                        <button type="button" className="toggle-btn">Sign Up</button>
                    </div>
                    <div className="social-icons">
                        <img src="fb.png" alt="Facebook" />
                        <img src="gb.png" alt="Google" />
                    </div>
                    <form className="input-group">
                        {contantformm.map(field => (
                            <div className="input-pair">
                                <input type={field.type} className={field.className} placeholder={field.placeholder} required />
                            </div>
                        ))}
                        <button type="submit" className="submit-btn">Sign Up</button>
                    </form>
                </div>
            </div>
        );
    }
}
